SELECT json_build_object(
 'columns', (SELECT coalesce(json_agg(json_build_object('name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) ORDER BY column_name),'[]'::json) FROM information_schema.columns WHERE table_schema='public' AND table_name='orders' AND column_name IN ('order_number','received_date','entrance','floor','intercom','amount_confirmed')),
 'functions', (SELECT coalesce(json_agg(json_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'md5',md5(p.prosrc),'language',l.lanname,'security_definer',p.prosecdef,'volatility',p.provolatile,'parallel',p.proparallel,'config',p.proconfig) ORDER BY p.proname,p.oid),'[]'::json) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('bos_order_number_source','bos_check_manual_order_number','bos_confirm_order_amount_on_change')),
 'constraints', (SELECT coalesce(json_agg(json_build_object('name',conname,'valid',convalidated,'definition',pg_get_constraintdef(oid)) ORDER BY conname),'[]'::json) FROM pg_constraint WHERE conrelid='public.orders'::regclass AND conname='orders_manual_number_valid'),
 'indexes', (SELECT coalesce(json_agg(json_build_object('name',c.relname,'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY c.relname),'[]'::json) FROM pg_class c JOIN pg_index i ON i.indexrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relname='orders_manual_number_unique'),
 'triggers', (SELECT coalesce(json_agg(json_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid)) ORDER BY tgname),'[]'::json) FROM pg_trigger WHERE tgrelid='public.orders'::regclass AND tgname IN ('orders_check_manual_number','zz_bos_confirm_order_amount'))
)
